/** static u8 AppendCaughtBannedMonSpeciesName(u16 species, u8 count, s32 numBannedMonsCaught) */
export function AppendCaughtBannedMonSpeciesName(species: any, count: any, numBannedMonsCaught: any): any {
  if (GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT))
      {
          count++;
          switch (count)
          {
          case 1:
          case 3:
          case 5:
          case 7:
          case 9:
          case 11:
              if (numBannedMonsCaught == count)
                  StringAppend(gStringVar1, gText_SpaceAndSpace);
              else if (numBannedMonsCaught > count)
                  StringAppend(gStringVar1, gText_CommaSpace);
              break;
          case 2:
              if (count == numBannedMonsCaught)
                  StringAppend(gStringVar1, gText_SpaceAndSpace);
              else
                  StringAppend(gStringVar1, gText_CommaSpace);
              StringAppend(gStringVar1, gText_NewLine);
              break;
          default:
              if (count == numBannedMonsCaught)
                  StringAppend(gStringVar1, gText_SpaceAndSpace);
              else
                  StringAppend(gStringVar1, gText_CommaSpace);
              StringAppend(gStringVar1, gText_LineBreak);
              break;
          }
          StringAppend(gStringVar1, gSpeciesNames[species]);
      }

      return count;
}

/** static void AppendIfValid(u16 species, u16 heldItem, u16 hp, u8 lvlMode, u8 monLevel, u16 *speciesArray, u16 *itemsArray, u8 *count) */
export function AppendIfValid(species: any, heldItem: any, hp: any, lvlMode: any, monLevel: any, speciesArray: any, itemsArray: any, count: any): any {
  let i: any = 0;

      if (species == (412) || species == (0))
          return;

      for (i = 0; gFrontierBannedSpecies[i] != 0xFFFF && gFrontierBannedSpecies[i] != species; i++)
          ;

      if (gFrontierBannedSpecies[i] != 0xFFFF)
          return;
      if (lvlMode == (0) && monLevel > (50))
          return;

      for (i = 0; i < count && speciesArray[i] != species; i++)
          ;
      if (i != count)
          return;

      if (heldItem != 0)
      {
          for (i = 0; i < count && itemsArray[i] != heldItem; i++)
              ;
          if (i != count)
              return;
      }

      speciesArray[count] = species;
      itemsArray[count] = heldItem;
      count++;
}

/** static void CheckPartyIneligibility(void) */
export function CheckPartyIneligibility(): any {
  let speciesArray: any = [];
      let itemArray: any = [];
      let monId: any = 0;
      let toChoose: any = 0;
      let count: any = 0;
      let battleMode: any = VarGet((0x40CE));
      let monIdLooper: any = null;

      switch (battleMode)
      {
      case (0):
          toChoose = (3);
          break;
      case (2):
      case (3):
          toChoose = (2);
          break;
      case (1):
          if (VarGet((0x40CF)) == (0))
              toChoose = (4);
          else
              toChoose = (3);
          break;
      }

      monIdLooper = 0;
      do
      {
          monId = monIdLooper;
          numEligibleMons = 0;
          do
          {
              let species: any = GetMonData(gPlayerParty[monId], MON_DATA_SPECIES_OR_EGG);
              let heldItem: any = GetMonData(gPlayerParty[monId], MON_DATA_HELD_ITEM);
              let level: any = GetMonData(gPlayerParty[monId], MON_DATA_LEVEL);
              let hp: any = GetMonData(gPlayerParty[monId], MON_DATA_HP);
              if (VarGet((0x40CF)) == (6))
              {
                  if (heldItem == (0))
                      AppendIfValid(species, heldItem, hp, gSpecialVar_Result, level, speciesArray, itemArray,numEligibleMons);
              }
              else
              {
                  AppendIfValid(species, heldItem, hp, gSpecialVar_Result, level, speciesArray, itemArray,numEligibleMons);
              }
              monId++;
              if (monId >= (6))
                  monId = 0;
          } while (monId != monIdLooper);

          monIdLooper++;
      } while (monIdLooper < (6) && numEligibleMons < toChoose);

      if (numEligibleMons < toChoose)
      {
          let i: any = null;
          let caughtBannedMons: any = 0;
          let species: any = gFrontierBannedSpecies[0];
          for (i = 0; species != 0xFFFF; i++, species = gFrontierBannedSpecies[i])
          {
              if (GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT))
                  caughtBannedMons++;
          }
          gStringVar1[0] = (0xFF);
          gSpecialVar_0x8004 = TRUE;
          count = 0;
          for (i = 0; gFrontierBannedSpecies[i] != 0xFFFF; i++)
              count = AppendCaughtBannedMonSpeciesName(gFrontierBannedSpecies[i], count, caughtBannedMons);

          if (count == 0)
          {
              StringAppend(gStringVar1, gText_Space2);
              StringAppend(gStringVar1, gText_Are);
          }
          else
          {
              if (count & 1)
                  StringAppend(gStringVar1, gText_LineBreak);
              else
                  StringAppend(gStringVar1, gText_Space2);
              StringAppend(gStringVar1, gText_Are2);
          }
      }
      else
      {
          gSpecialVar_0x8004 = FALSE;
          gSaveBlock2Ptr.frontier.lvlMode = gSpecialVar_Result;
      }

}

